/**
 * Fontes e logo da marca embutidos para o PDF do certificado sem arte: o runtime da VPS
 * não tem a pasta public/ nem acesso a fontes externas.
 * Fraunces (títulos) e Inter Tight (texto), instâncias estáticas em subconjunto latino,
 * ambas sob SIL OFL 1.1.
 */
const decode = (value: string) => Buffer.from(value, 'base64');

const fraunces600Base64 =
  '';

const interTight400Base64 =
  '';

const interTight600Base64 =
  '';

const interTight800Base64 =
  '';

const logoWhiteBase64 =
  '';

export const certificateAssets = {
  fraunces600: () => decode(fraunces600Base64),
  interTight400: () => decode(interTight400Base64),
  interTight600: () => decode(interTight600Base64),
  interTight800: () => decode(interTight800Base64),
  logoWhite: () => decode(logoWhiteBase64),
};
